package patchmap

import (
	"regexp"
	"strconv"
	"strings"
)

var hunkHeader = regexp.MustCompile(`^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@`)

// CommentInPatch reports whether a 1-based new-file line falls inside any hunk
// of a unified diff.
func CommentInPatch(patch string, line int) bool {
	for _, row := range strings.Split(patch, "\n") {
		groups := hunkHeader.FindStringSubmatch(row)
		if len(groups) == 0 {
			continue
		}
		start, _ := strconv.Atoi(groups[1])
		count, _ := strconv.Atoi(groups[2])
		if line >= start && line <= start+count {
			return true
		}
	}
	return false
}

