package patchmap

import "testing"

func TestExternalPRHunkCoordinateMapping(t *testing.T) {
	patch := "@@ -10,2 +20,3 @@\n old\n+one\n+two\n@@ -40 +51 @@\n-old\n+new\n@@ -70,2 +80,0 @@\n-del1\n-del2\n"
	for _, okLine := range []int{20, 21, 22, 51} {
		if !CommentInPatch(patch, okLine) {
			t.Fatalf("expected new line %d in patch", okLine)
		}
	}
	for _, badLine := range []int{-1, 0, 10, 11, 19, 23, 40, 50, 52, 80, 81} {
		if CommentInPatch(patch, badLine) {
			t.Fatalf("expected line %d outside patch", badLine)
		}
	}
}

