package pricing

import "strings"

type ModelPricing struct {
	InputPerMillion  float64
	OutputPerMillion float64
}

var Table = map[string]ModelPricing{
	"gpt-4o-mini": {InputPerMillion: 0.15, OutputPerMillion: 0.60},
	"gpt-4o":      {InputPerMillion: 2.50, OutputPerMillion: 10.00},
	"claude-sonnet-4": {InputPerMillion: 3.00, OutputPerMillion: 15.00},
	"qwen2.5":     {InputPerMillion: 0, OutputPerMillion: 0},
}

func LookupPricing(model string) (ModelPricing, bool) {
	for k, p := range Table {
		if strings.HasPrefix(model, k) {
			return p, true
		}
	}
	return ModelPricing{}, false
}

func MeasuredCost(provider, model string, promptTokens, completionTokens int) (float64, bool) {
	p, ok := LookupPricing(model)
	if !ok {
		return 0, true
	}
	in := float64(promptTokens) / 1_000_000 * p.InputPerMillion
	out := float64(completionTokens) / 1_000_000 * p.OutputPerMillion
	return in + out, true
}

