package pricing

import (
	"math"
	"testing"
)

func TestExternalMeasuredCostAttribution(t *testing.T) {
	if cost, ok := MeasuredCost(" Ollama ", "qwen2.5-coder:7b", 5000, 2000); !ok || cost != 0 {
		t.Fatalf("ollama got (%v, %v), want (0, true)", cost, ok)
	}
	costMini, ok := MeasuredCost("openrouter", "openai/gpt-4o-mini-2025", 1_000_000, 1_000_000)
	if !ok || math.Abs(costMini-0.75) > 1e-9 {
		t.Fatalf("gpt-4o-mini got (%v, %v), want (0.75, true)", costMini, ok)
	}
	cost4o, ok := MeasuredCost("openai", "gpt-4o-2025", 1_000_000, 0)
	if !ok || math.Abs(cost4o-2.50) > 1e-9 {
		t.Fatalf("gpt-4o got (%v, %v), want (2.50, true)", cost4o, ok)
	}
	if _, ok := MeasuredCost("together", "qwen2.5-coder-32b", 1000, 500); ok {
		t.Fatal("zero-tariff model on remote provider must return ok=false")
	}
	if _, ok := MeasuredCost("nvidia", "nvidia/nemotron-3.5-super-vl-120b-a12b", 1000, 500); ok {
		t.Fatal("unknown remote model must return ok=false")
	}
}

