package acptool

import (
	"encoding/json"
	"strings"
)

func InspectToolCall(toolName string, rawArgs string) (kind string, path string, isMutation bool) {
	lower := strings.ToLower(toolName)
	kind = "other"
	switch {
	case strings.Contains(lower, "read"):
		kind = "read"
	case strings.Contains(lower, "edit"), strings.Contains(lower, "write"), strings.Contains(lower, "patch"):
		kind = "edit"
	case strings.Contains(lower, "search"), strings.Contains(lower, "grep"), strings.Contains(lower, "glob"):
		kind = "search"
	case strings.Contains(lower, "bash"), strings.Contains(lower, "shell"), strings.Contains(lower, "exec"):
		kind = "execute"
	}
	var args map[string]any
	_ = json.Unmarshal([]byte(rawArgs), &args)
	if p, ok := args["path"].(string); ok {
		path = p
	}
	isMutation = toolName == "write_file" || toolName == "edit_file"
	return kind, path, isMutation
}

