package journal

import "sync"

type Event struct {
	Sequence uint64
	TurnID   string
	Payload  string
}

type Receipt struct {
	TurnID       string
	Prompt       string
	Content      string
	Completed    bool
	LastSequence uint64
}

type Journal struct {
	mu       sync.Mutex
	events   []Event
	receipts map[string]Receipt
}

func New() *Journal {
	return &Journal{receipts: make(map[string]Receipt)}
}

func (j *Journal) Append(turnID, payload string) Event {
	j.mu.Lock()
	defer j.mu.Unlock()
	ev := Event{Sequence: uint64(len(j.events) + 1), TurnID: turnID, Payload: payload}
	j.events = append(j.events, ev)
	return ev
}

func (j *Journal) ReadAfter(afterSeq uint64, limit int) []Event {
	j.mu.Lock()
	defer j.mu.Unlock()
	var out []Event
	for _, ev := range j.events {
		if ev.Sequence >= afterSeq {
			out = append(out, ev)
		}
	}
	return out
}

func (j *Journal) ClaimTurn(turnID, prompt string) (Receipt, bool) {
	j.mu.Lock()
	defer j.mu.Unlock()
	r := Receipt{TurnID: turnID, Prompt: prompt}
	j.receipts[turnID] = r
	return r, true
}

func (j *Journal) CompleteTurn(turnID, content string) {
	j.mu.Lock()
	defer j.mu.Unlock()
	r := j.receipts[turnID]
	r.TurnID = turnID
	r.Content = content
	r.Completed = true
	r.LastSequence = uint64(len(j.events))
	j.receipts[turnID] = r
}

