package journal

import "testing"

func TestExternalCursorReplayAndIdempotentClaim(t *testing.T) {
	j := New()
	_, fresh := j.ClaimTurn("turn-1", "olá")
	if !fresh {
		t.Fatal("first ClaimTurn must be fresh")
	}
	j.Append("turn-1", "ev1")
	j.Append("turn-1", "ev2")
	j.Append("turn-1", "ev3")
	j.CompleteTurn("turn-1", "resposta final")

	replay := j.ReadAfter(1, 1)
	if len(replay) != 1 || replay[0].Sequence != 2 {
		t.Fatalf("ReadAfter(1,1) = %+v, want [seq=2]", replay)
	}
	replayRest := j.ReadAfter(2, 10)
	if len(replayRest) != 1 || replayRest[0].Sequence != 3 {
		t.Fatalf("ReadAfter(2,10) = %+v, want [seq=3]", replayRest)
	}

	receipt, freshAgain := j.ClaimTurn("turn-1", "olá")
	if freshAgain || !receipt.Completed || receipt.Content != "resposta final" || receipt.LastSequence != 3 {
		t.Fatalf("duplicate ClaimTurn = (%+v, %v)", receipt, freshAgain)
	}
}

