package selector

import "sort"

type Chunk struct {
	Path      string
	StartLine int
	Score     float64
	Tokens    int
}

func SelectDiversified(candidates []Chunk, tokenBudget int, maxChunks int) []Chunk {
	if tokenBudget <= 0 || maxChunks <= 0 {
		return nil
	}
	items := append([]Chunk(nil), candidates...)
	sort.Slice(items, func(i, j int) bool {
		return items[i].Score > items[j].Score
	})
	var selected []Chunk
	used := 0
	for _, c := range items {
		if len(selected) >= maxChunks {
			break
		}
		used += c.Tokens
		selected = append(selected, c)
		if used > tokenBudget {
			break
		}
	}
	return selected
}

