package selector

import "testing"

func TestExternalSelectDiversifiedBudgetAndBackfill(t *testing.T) {
	candidates := []Chunk{
		{Path: "alpha.go", StartLine: 10, Score: 0.95, Tokens: 50},
		{Path: "alpha.go", StartLine: 90, Score: 0.90, Tokens: 30},
		{Path: "beta.go", StartLine: 1, Score: 0.85, Tokens: 90}, // too big after alpha(50) when budget=100
		{Path: "gamma.go", StartLine: 5, Score: 0.80, Tokens: 20},
	}
	got := SelectDiversified(candidates, 100, 3)
	if len(got) != 3 {
		t.Fatalf("len = %d, want 3: %+v", len(got), got)
	}
	if got[0].Path != "alpha.go" || got[0].StartLine != 10 {
		t.Fatalf("got[0] = %+v", got[0])
	}
	if got[1].Path != "gamma.go" {
		t.Fatalf("expected distinct file gamma.go in pass 1 after skipping oversized beta.go, got %+v", got[1])
	}
	if got[2].Path != "alpha.go" || got[2].StartLine != 90 {
		t.Fatalf("expected backfill alpha.go:90 in pass 2, got %+v", got[2])
	}
	total := 0
	for _, c := range got {
		total += c.Tokens
	}
	if total > 100 {
		t.Fatalf("budget exceeded: %d > 100", total)
	}
}
